<?php $editing=isset($step); $row=$step ?? []; ?><form class="stack" action="/growth/<?= e($goal['id']) ?>/steps<?= $editing ? '/'.e($step['id']).'/edit' : '' ?>" method="post"><?= csrf_field() ?><label>Actionable step<input name="title" value="<?= e($row['title'] ?? '') ?>" maxlength="200" required></label><label>Due date (optional)<input type="date" name="due_date" value="<?= e($row['due_date'] ?? '') ?>"></label><label>Prerequisite step<select name="depends_on"><option value="">No prerequisite</option><?php foreach ($steps as $option) if (!$editing || $option['id']!==$step['id']): ?><option value="<?= e($option['id']) ?>" <?= ($row['depends_on'] ?? null)===$option['id'] ? 'selected' : '' ?>><?= e($option['title']) ?> · <?= e($option['status']) ?></option><?php endif; ?></select></label><label><input type="checkbox" name="is_milestone" value="1" <?= !empty($row['is_milestone']) ? 'checked' : '' ?>>This step is a milestone</label><button><?= $editing ? 'Save step' : 'Add step' ?></button></form>
